/* Signature Slovak Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Janomir": "From Jan + mir (peace).", "Marzuzana": "From Maria + Zuzana.", "Petromil": "From Peter + mil (dear): 'dear rock'.", "Evaslava": "From Eva + slava (glory).", "Martinko": "From Martin + -ko.", "Zuzamir": "From Zuzana + mir.", "Janomirov": "Signature surname in -ov style; feminine Janomirova.", "Petromilov": "Signature surname; feminine Petromilova.", "Evaslavov": "Signature surname; feminine Evaslavova.", "Martinkov": "Signature surname; feminine Martinkova."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Janomir';
console.log(lookup(q));

